--!strict
local Players=game:GetService("Players");local ReplicatedStorage=game:GetService("ReplicatedStorage");local player=Players.LocalPlayer;local folder=ReplicatedStorage:WaitForChild("Remotes",10);if not folder then return end;local progress=folder:WaitForChild("TowerProgressUpdated")::RemoteEvent;local back=folder:WaitForChild("ReturnToLobby")::RemoteEvent
local gui=Instance.new("ScreenGui");gui.Name="TowerGui";gui.ResetOnSpawn=false;gui.Enabled=false;gui.Parent=player.PlayerGui;local frame=Instance.new("Frame");frame.Position=UDim2.fromScale(.03,.05);frame.Size=UDim2.fromScale(.25,.16);frame.BackgroundColor3=Color3.fromRGB(35,30,55);frame.BackgroundTransparency=.12;frame.Parent=gui;local label=Instance.new("TextLabel");label.Size=UDim2.fromScale(1,.65);label.BackgroundTransparency=1;label.TextColor3=Color3.new(1,1,1);label.TextScaled=true;label.Parent=frame;local button=Instance.new("TextButton");button.Position=UDim2.fromScale(.15,.7);button.Size=UDim2.fromScale(.7,.23);button.Text="返回大廳";button.TextScaled=true;button.Parent=frame;button.Activated:Connect(function()back:FireServer() end)
progress.OnClientEvent:Connect(function(d)gui.Enabled=true;if d.countdown then label.Text=tostring(d.countdown) elseif d.completed then label.Text=string.format("完成！%.2f 秒\n最佳 %.2f",d.time,d.best) else label.Text=string.format("樓層 %d/%d\n最佳：%s",d.floor,d.total,(d.best or 0)>0 and string.format("%.2f",d.best) or "--") end end)
local modeState=folder:WaitForChild("ModeStateChanged")::RemoteEvent;modeState.OnClientEvent:Connect(function(d)if d.inLobby then gui.Enabled=false end end)
